const input = $input.first().json || {};
const message = String(input.user_message || input.message || '').toLowerCase();
const eventName = input.event_context?.event_name || null;

// Lista ficticia de eventos para la entrega académica.
const events = [
  {
    event_name: 'Noche de Teatro Independiente',
    event_date: '2026-09-12',
    event_time: '20:30',
    price: 12000,
    currency: 'ARS',
    availability: 'disponible',
    purchase_channel: 'boletería web'
  },
  {
    event_name: 'Ciclo de Jazz en Sala',
    event_date: '2026-09-22',
    event_time: '20:00',
    price: 0,
    currency: 'ARS',
    availability: 'entrada gratuita con reserva',
    purchase_channel: 'reserva online'
  },
  {
    event_name: 'Taller de Movimiento Escénico',
    event_date: '2026-10-05',
    event_time: '18:00',
    price: 18000,
    currency: 'ARS',
    availability: 'últimos lugares',
    purchase_channel: 'formulario de inscripción'
  }
];

let selected = null;
if (eventName) {
  selected = events.find(e => e.event_name.toLowerCase().includes(String(eventName).toLowerCase()));
}
if (!selected) {
  selected = events.find(e => message.includes(e.event_name.toLowerCase().split(' ')[0]));
}

let response;
if (selected) {
  const priceText = selected.price === 0 ? 'entrada gratuita con reserva' : `$${selected.price.toLocaleString('es-AR')} ${selected.currency}`;
  response = `Para ${selected.event_name}, la función figura el ${selected.event_date} a las ${selected.event_time}. Valor: ${priceText}. Disponibilidad: ${selected.availability}. Canal sugerido: ${selected.purchase_channel}.`;
} else {
  response = 'Tenemos eventos culturales con venta o reserva activa. Para informar precio exacto necesito el nombre de la función, fecha o actividad de interés.';
}

return [{
  json: {
    status: 'success',
    worker: 'worker_venta_cultural',
    intent: input.intent || 'VENTA',
    request_id: input.request_id || null,
    session_id: input.session_id || null,
    response,
    data: {
      matched_event: selected,
      available_events_count: events.length
    },
    requires_human: false,
    next_action: selected ? 'responder_consulta_comercial' : 'solicitar_evento_o_fecha',
    error: null
  }
}];
